import{c as e,Q as n,j as a,m as o}from"./chunks/framework.g_l1frA7.js";const p=JSON.parse('{"title":"Onboarding","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/onboarding.md","filePath":"getting-started/onboarding.md","lastUpdated":null}'),i={name:"getting-started/onboarding.md"};function r(s,t,d,l,c,g){return n(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="onboarding" tabindex="-1">Onboarding <a class="header-anchor" href="#onboarding" aria-label="Permalink to &quot;Onboarding&quot;">​</a></h1><p>Onboarding is account-first. You land on it after creating the admin account; you can also re-run it from <strong>Settings</strong> via “Reset onboarding”.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><ol><li><strong>Choose how to start.</strong> Create a manual account (checking, savings, credit, investment, cash, loan, or other) or connect SimpleFIN.</li><li><strong>SimpleFIN (optional).</strong> Paste the access URL you obtained from your bank via SimpleFIN Bridge. FinSight exchanges it only when you explicitly connect and when you synchronize. The URL is stored inside your encrypted database, not a global secret store.</li><li><strong>Import CSV history (optional).</strong> Upload a CSV in the import drawer. FinSight parses and stages candidates, deduplicates against existing transactions, and shows a review queue before finalizing. You can import years of history here.</li><li><strong>Categories.</strong> Keep the seeded set or tailor it. Every category carries a <code>spending_type</code> (Need/Want/Saving/Investment) that powers the Conscious Spending view on Budget and the Copilot’s allocation checks.</li><li><strong>Provider (optional).</strong> Configure an AI provider if you want auto-categorization and the Copilot. Skip it to run fully offline; you can add it later at <strong>Settings → Agent</strong>.</li></ol><p>Progress is persisted — you can close the tab and return. The “Reset onboarding” control in Settings clears the onboarding-seen flag for testing and returns you to the wizard flow.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>For manual accounts, balance history is derived from transactions; you do not enter a separate balance ledger.</li><li>SimpleFIN accounts show a sync status and last-run timestamp. Use <strong>Accounts → Synchronize</strong> to pull new activity.</li><li>If you imported CSVs and see unconverted currencies, check <a href="/FinSight/guide/accounts">Currencies</a> — amounts without a known conversion are kept separate, never silently summed.</li></ul><p>Next: <a href="/FinSight/getting-started/importing-data">Importing Your Data</a>.</p>',8)])])}const h=e(i,[["render",r]]);export{p as __pageData,h as default};
